package com.example.api.tests;

import com.fasterxml.jackson.core.type.TypeReference;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

import static io.restassured.RestAssured.*;
import static org.hamcrest.Matchers.*;
import static org.junit.jupiter.api.Assertions.*;

/**
 * Comprehensive tests for the Orders endpoints:
 * - POST /orders
 * - GET /orders
 * - GET /orders/{order_id}
 *
 * Tests are written to validate both happy-path and various error/edge cases.
 */
public class OrdersApiTest extends BaseTest {

    private static final String DEFAULT_BROKER = "upstox";
    private static final int DEFAULT_USER_ID = 1;

    @BeforeAll
    public static void setup() {
        configureBaseUri();
    }

    private Map<String, Object> buildLimitOrderPayload() {
        Map<String, Object> body = new HashMap<>();
        body.put("tradingsymbol", "INFY");
        body.put("exchange", "NSE");
        body.put("quantity", 1);
        body.put("order_type", "LIMIT");
        body.put("price", 1000.0);
        body.put("product", "CNC");
        body.put("transaction_type", "BUY");
        // optional fields can be added as needed
        return body;
    }

    /**
     * Happy path: Place an order with valid payload.
     * If the environment lacks credentials for the (user_id, broker) pair, the service is expected to return 404.
     * This test asserts either a successful 200 response with an order_id OR a proper 404 error envelope.
     */
    @Test
    public void testPostOrdersHappyPath_or_MissingCredentialsHandled() {
        Map<String, Object> payload = buildLimitOrderPayload();
        // make unique to help brokers that might dedupe
        payload.put("client_order_id", "test-" + UUID.randomUUID());

        int status = given()
            .contentType(ContentType.JSON)
            .queryParam("broker", DEFAULT_BROKER)
            .queryParam("user_id", DEFAULT_USER_ID)
            .body(payload)
        .when()
            .post("/orders")
        .then()
            .extract()
            .statusCode();

        if (status == 200) {
            // Assert the response body contains order_id and status
            given()
                .contentType(ContentType.JSON)
                .queryParam("broker", DEFAULT_BROKER)
                .queryParam("user_id", DEFAULT_USER_ID)
                .body(payload)
            .when()
                .post("/orders")
            .then()
                .statusCode(200)
                .body("order_id", notNullValue())
                .body("status", notNullValue());
        } else if (status == 404) {
            // Validate HTTPException envelope shape: { status, message, detail, path }
            given()
                .contentType(ContentType.JSON)
                .queryParam("broker", DEFAULT_BROKER)
                .queryParam("user_id", DEFAULT_USER_ID)
                .body(payload)
            .when()
                .post("/orders")
            .then()
                .statusCode(404)
                .body("status", notNullValue())
                .body("message", notNullValue())
                .body("path", notNullValue());
        } else {
            // Accept validation errors as well (422/400)
            assertTrue(status == 422 || status == 400, "Unexpected HTTP status: " + status);
        }
    }

    /**
     * Validation error: Missing required field 'tradingsymbol' should result in 422/400.
     */
    @Test
    public void testPostOrdersValidationMissingRequiredField() {
        Map<String, Object> payload = buildLimitOrderPayload();
        payload.remove("tradingsymbol");

        given()
            .contentType(ContentType.JSON)
            .queryParam("broker", DEFAULT_BROKER)
            .queryParam("user_id", DEFAULT_USER_ID)
            .body(payload)
        .when()
            .post("/orders")
        .then()
            .statusCode(anyOf(is(422), is(400)))
            .body("$", notNullValue()); // validation envelope
    }

    /**
     * Validation error: quantity <= 0 should be rejected.
     */
    @Test
    public void testPostOrdersValidationQuantityNonPositive() {
        Map<String, Object> payload = buildLimitOrderPayload();
        payload.put("quantity", 0);

        given()
            .contentType(ContentType.JSON)
            .queryParam("broker", DEFAULT_BROKER)
            .queryParam("user_id", DEFAULT_USER_ID)
            .body(payload)
        .when()
            .post("/orders")
        .then()
            .statusCode(anyOf(is(422), is(400)));
    }

    /**
     * Validation error: LIMIT order without price should be rejected.
     */
    @Test
    public void testPostOrdersLimitRequiresPrice() {
        Map<String, Object> payload = buildLimitOrderPayload();
        payload.remove("price");

        given()
            .contentType(ContentType.JSON)
            .queryParam("broker", DEFAULT_BROKER)
            .queryParam("user_id", DEFAULT_USER_ID)
            .body(payload)
        .when()
            .post("/orders")
        .then()
            .statusCode(anyOf(is(422), is(400)));
    }

    /**
     * Validation error: SL order requires trigger_price.
     */
    @Test
    public void testPostOrdersSlRequiresTriggerPrice() {
        Map<String, Object> payload = buildLimitOrderPayload();
        payload.put("order_type", "SL");
        payload.remove("price");
        payload.remove("trigger_price"); // ensure missing

        given()
            .contentType(ContentType.JSON)
            .queryParam("broker", DEFAULT_BROKER)
            .queryParam("user_id", DEFAULT_USER_ID)
            .body(payload)
        .when()
            .post("/orders")
        .then()
            .statusCode(anyOf(is(422), is(400)));
    }

    /**
     * Edge case: List orders for a user. If service returns 200, ensure a list response structure. If 404 due to missing credentials, validate envelope.
     */
    @Test
    public void testGetOrdersList() {
        int status = given()
            .queryParam("broker", DEFAULT_BROKER)
            .queryParam("user_id", DEFAULT_USER_ID)
        .when()
            .get("/orders")
        .then()
            .extract()
            .statusCode();

        if (status == 200) {
            // ensure response matches expected ListOrdersResponse (array or object with data)
            List<?> lst = given()
                .queryParam("broker", DEFAULT_BROKER)
                .queryParam("user_id", DEFAULT_USER_ID)
            .when()
                .get("/orders")
            .then()
                .statusCode(200)
                .extract()
                .jsonPath()
                .getList("$");

            assertNotNull(lst);
            // empty list is allowed
            assertTrue(lst.size() >= 0);
        } else {
            // 404 due to missing credentials or other envelopes
            given()
                .queryParam("broker", DEFAULT_BROKER)
                .queryParam("user_id", DEFAULT_USER_ID)
            .when()
                .get("/orders")
            .then()
                .statusCode(404)
                .body("status", notNullValue())
                .body("message", notNullValue());
        }
    }

    /**
     * Create an order then fetch it by order_id. Validates Get Order happy path; if environment doesn't allow create, test attempts to GET a known-nonsense id to exercise 404.
     */
    @Test
    public void testGetOrderByIdHappyPathOrNotFound() throws Exception {
        // Try to create an order first
        Map<String, Object> payload = buildLimitOrderPayload();
        payload.put("client_order_id", "test-" + UUID.randomUUID());

        io.restassured.response.Response resp = given()
            .contentType(ContentType.JSON)
            .queryParam("broker", DEFAULT_BROKER)
            .queryParam("user_id", DEFAULT_USER_ID)
            .body(payload)
        .when()
            .post("/orders")
        .then()
            .extract()
            .response();

        int status = resp.statusCode();
        if (status == 200) {
            String orderId = resp.jsonPath().getString("order_id");
            assertNotNull(orderId);

            // Now GET by id
            given()
                .queryParam("broker", DEFAULT_BROKER)
                .queryParam("user_id", DEFAULT_USER_ID)
            .when()
                .get("/orders/{order_id}", orderId)
            .then()
                .statusCode(200)
                .body("order_id", equalTo(orderId))
                .body("status", notNullValue());
        } else if (status == 404) {
            // If creation fails due to missing credentials, attempt to GET a deterministic non-existent order id to assert 404 envelope
            given()
                .queryParam("broker", DEFAULT_BROKER)
                .queryParam("user_id", DEFAULT_USER_ID)
            .when()
                .get("/orders/{order_id}", "nonexistent-order-12345")
            .then()
                .statusCode(404)
                .body("status", notNullValue())
                .body("message", notNullValue());
        } else {
            // Accept validation errors
            assertTrue(status == 422 || status == 400);
        }
    }

    /**
     * Validation: invalid order_id path parameter should be rejected when it contains invalid characters.
     * According to the spec, order_id must match [a-zA-Z0-9_.-]+. Provide an invalid one to trigger 422/400.
     */
    @Test
    public void testGetOrderInvalidOrderIdPattern() {
        String invalidOrderId = "with spaces & symbols!";

        given()
            .queryParam("broker", DEFAULT_BROKER)
            .queryParam("user_id", DEFAULT_USER_ID)
        .when()
            .get("/orders/{order_id}", invalidOrderId)
        .then()
            .statusCode(anyOf(is(422), is(400)));
    }

    /**
     * Not found: request for an order_id that is syntactically valid but non-existent should return 404.
     * This test will assert a 404 envelope IF the service recognizes the user/broker credentials; otherwise, a 404 for missing credentials is acceptable.
     */
    @Test
    public void testGetOrderNotFoundForNonExistentId() {
        String nonExistentId = "order-" + UUID.randomUUID().toString().replaceAll("[^a-zA-Z0-9_.-]", "a");

        int status = given()
            .queryParam("broker", DEFAULT_BROKER)
            .queryParam("user_id", DEFAULT_USER_ID)
        .when()
            .get("/orders/{order_id}", nonExistentId)
        .then()
            .extract()
            .statusCode();

        // If the service recognizes credentials and the id is missing, it should be 404.
        assertTrue(status == 404 || status == 422 || status == 400 || status == 200);
        // If 200 occurs unexpectedly, ensure response shape contains order fields or empty (defensive).
    }

    /**
     * Authentication/Authorization: The service does not perform end-user auth in this scope, but upstream gateways might.
     * This test attempts a request with an Authorization header and asserts that the service either ignores it (200/404/422)
     * or enforces auth (401/403). We accept either behavior but assert that returned codes are meaningful.
     */
    @Test
    public void testAuthHeaderBehavior() {
        Map<String, Object> payload = buildLimitOrderPayload();
        payload.put("client_order_id", "auth-test-" + UUID.randomUUID());

        int status = given()
            .contentType(ContentType.JSON)
            .header("Authorization", "Bearer invalid-token")
            .queryParam("broker", DEFAULT_BROKER)
            .queryParam("user_id", DEFAULT_USER_ID)
            .body(payload)
        .when()
            .post("/orders")
        .then()
            .extract()
            .statusCode();

        // Acceptable outcomes: 200 (service ignores auth), 401/403 (auth enforced), 404 (missing credentials), or 422/400 (validation)
        assertTrue(status == 200 || status == 401 || status == 403 || status == 404 || status == 422 || status == 400,
                "Unexpected status code for auth behavior: " + status);
    }
}

